    };
  }

  var datasets = [
    ds('sig', dSig, C.sig, 2.2),
    ds('envU', dEnvU, C.am, 1.3, dash(5, 4)),
    ds('envL', dEnvL, C.am, 1.3, dash(5, 4)),
    ds('am', dAM, C.am, 2.2),
    ds('fm', dFM, C.fm, 2.2),
    ds('recAM', dRecAM, C.rec, 1.3, dash(6, 4)),
    ds('recFM', dRecFM, C.rec, 1.3, dash(6, 4))
  ];
  datasets[1].hidden = datasets[2].hidden = datasets[5].hidden = datasets[6].hidden = true;

  /* ---------- overlay plugin ---------- */
  var overlay = {
    id: 'figOverlay',
    beforeLayout: function (chart) {
      var b = baseOf(chart);
      chart.options.layout.padding = {
        left: 4, top: 6 * b, bottom: 4,
        right: Math.max(44, 50 * b)
      };
    },
    afterDatasetsDraw: function (chart) {
      var ctx = chart.ctx, ca = chart.chartArea, xs = chart.scales.x, ys = chart.scales.y;
      var b = baseOf(chart);
      var fs = Math.max(9, 15 * b);
      ctx.save();

      /* --- right-margin trace labels --- */
      ctx.font = fs + 'px sans-serif';
      ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
      ctx.fillStyle = '#111';
      ctx.fillText('Signal', ca.right + 6 * b, ys.getPixelForValue(SIG_Y + SIG_A * mAt(1)));
      ctx.fillStyle = (mode === 'fm') ? '#999' : '#111';
      ctx.fillText('AM', ca.right + 6 * b, ys.getPixelForValue(AM_Y));
      ctx.fillStyle = (mode === 'am') ? '#999' : '#111';
      ctx.fillText('FM', ca.right + 6 * b, ys.getPixelForValue(FM_Y));

      /* --- marker line + intersection dots --- */
      if (markerActive) {
        var px = xs.getPixelForValue(markerT);
        ctx.beginPath();
        ctx.setLineDash([Math.max(3, 4 * b), Math.max(3, 3 * b)]);
        ctx.lineWidth = Math.max(0.8, 1.2 * b);
        ctx.strokeStyle = C.marker;
        ctx.moveTo(px, ys.getPixelForValue(9.55));
        ctx.lineTo(px, ys.getPixelForValue(0.30));
        ctx.stroke();
        ctx.setLineDash([]);

        var r = Math.max(2, 3.6 * b);
        var dots = [
          [SIG_Y + SIG_A * mAt(markerT), C.sig],
          [amAt(markerT), (mode === 'fm') ? '#bbb' : C.am],
          [fmAt(markerT), (mode === 'am') ? '#bbb' : C.fm]
        ];
        if (showEnv && mode !== 'fm') {
          dots.push([AM_Y + AM_A * envAt(markerT), C.am]);
          dots.push([AM_Y - AM_A * envAt(markerT), C.am]);
          dots.push([REC_AM_Y + REC_A * mAt(markerT), C.rec]);
        }
        if (showEnv && mode !== 'am') dots.push([REC_FM_Y + REC_A * mAt(markerT), C.rec]);
        for (var k = 0; k < dots.length; k++) {
          ctx.beginPath();
          ctx.arc(px, ys.getPixelForValue(dots[k][0]), r, 0, 2 * Math.PI);
          ctx.fillStyle = dots[k][1]; ctx.fill();
          ctx.lineWidth = Math.max(0.6, 1 * b); ctx.strokeStyle = '#fff'; ctx.stroke();
        }
      }

      /* --- bottom strip: readout box (left) + annotations (right) --- */
      var stripTop = ys.getPixelForValue(-0.30);
      var stripBot = ys.getPixelForValue(Y_MIN + 0.05);
      var boxRight = ca.left;

      if (markerActive) {
        var t = markerT, m = mAt(t), e = envAt(t), f = fInst(t);
        var lines = [
          ['t = ' + t.toFixed(2), '#444'],
          ['signal   m = ' + (m >= 0 ? '+' : '') + m.toFixed(2), C.sig],
          ['AM envelope = ' + e.toFixed(2) + ' × max', C.am],
          ['FM  f = ' + (f / FC_FM).toFixed(2) + ' fc,  cycle gap = ' + (100 / f).toFixed(1) + '% W', C.fm]
        ];
        var rf = Math.max(8, 11.5 * b);
        ctx.font = rf + 'px sans-serif';
        var wmax = 0;
        for (var j = 0; j < lines.length; j++) wmax = Math.max(wmax, ctx.measureText(lines[j][0]).width);
        var pad = 6 * b + 3, lh = rf * 1.28;
        var bw = wmax + 2 * pad, bh = lines.length * lh + 2 * pad * 0.6;
        var bx = ca.left + 2, by = Math.max(stripTop, stripBot - bh);
        ctx.fillStyle = 'rgba(255,255,255,0.92)';
        ctx.strokeStyle = 'rgba(0,0,0,0.22)';
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.rect(bx, by, bw, bh); ctx.fill(); ctx.stroke();
        ctx.textAlign = 'left'; ctx.textBaseline = 'top';
        for (var q = 0; q < lines.length; q++) {
          ctx.fillStyle = lines[q][1];
          ctx.fillText(lines[q][0], bx + pad, by + pad * 0.6 + q * lh + lh * 0.12);
        }
        boxRight = bx + bw;
      }

      if (showEnv) {
        var af = Math.max(8, 11 * b);
        ctx.font = af + 'px sans-serif';
        var a1 = 'AM — amplitude varies, spacing constant';
        var a2 = 'FM — spacing varies, amplitude constant';
        var need = Math.max(ctx.measureText(a1).width, ctx.measureText(a2).width);
        if (ca.right - boxRight > need + 16 * b) {
          ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
          var midY = (stripTop + stripBot) / 2;
          ctx.fillStyle = (mode === 'fm') ? '#bbb' : C.am;
          ctx.fillText(a1, ca.right, midY - af * 0.75);
          ctx.fillStyle = (mode === 'am') ? '#bbb' : C.fm;
          ctx.fillText(a2, ca.right, midY + af * 0.75);
        }
      }
      ctx.restore();
    }
  };

  /* ---------- chart ---------- */
  var chart = new Chart(canvas.getContext('2d'), {
    type: 'line',
    data: { datasets: datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: false,
      parsing: false,
      normalized: true,
      events: [],
      layout: { padding: { left: 4, right: 50, top: 8, bottom: 4 } },
      scales: {
        x: { type: 'linear', min: 0, max: 1, display: false },
        y: { type: 'linear', min: Y_MIN, max: Y_MAX, display: false }
      },
      plugins: { legend: { display: false }, tooltip: { enabled: false } }
    },
    plugins: [overlay]
  });
  window.__markRendered();

  document.addEventListener('fig-resize', function () { chart.resize(); });

  /* ---------- state application ---------- */
  function byId(id) { for (var i = 0; i < datasets.length; i++) if (datasets[i]._id === id) return datasets[i]; }
  function refresh() {
    byId('am').borderColor = (mode === 'fm') ? C.dim : C.am;
    byId('fm').borderColor = (mode === 'am') ? C.dim : C.fm;
    byId('sig').borderColor = C.sig;
    var envOn = showEnv && mode !== 'fm';
    byId('envU').hidden = !envOn;
    byId('envL').hidden = !envOn;
    byId('recAM').hidden = !(showEnv && mode !== 'fm');
    byId('recFM').hidden = !(showEnv && mode !== 'am');
    chart.update('none');
  }

  window.update_timeMarker = function (v) {
    markerT = Math.max(0, Math.min(1, +v));
    markerActive = true;
    chart.render();
  };
  window.toggle_carrierMode = function (v) { mode = v; refresh(); };
  window.toggle_showEnvelope = function (on) { showEnv = !!on; refresh(); };

  /* ---------- pointer interaction ---------- */
  var dragging = false, moved = false, downX = 0, downY = 0;

  function bandAt(yPix) {
    var yv = chart.scales.y.getValueForPixel(yPix);
    if (yv > 6.2) return 'sig';
    if (yv > 2.6) return 'am';
    if (yv > -0.4) return 'fm';
    return null;
  }
  var TIPS = {
    sig: 'Message signal — the slow information waveform to be transmitted.',
    am: 'AM carrier — cycle spacing is constant; the amplitude follows the signal.',
    fm: 'FM carrier — amplitude is constant; the cycle spacing follows the signal.'
  };
  var POPS = {
    sig: ['Message signal', 'This slow black curve is the information (for example audio) that must be sent. On its own it cannot travel far as a radio wave, so it is written onto a much faster carrier wave.'],
    am: ['Amplitude modulation (AM)', 'The carrier keeps a fixed frequency, so its peaks stay evenly spaced. Instead the height of each cycle is scaled by the message, so the outline (envelope) of the peaks reproduces the original signal. Because the information lives in the amplitude, amplitude noise corrupts it directly.'],
    fm: ['Frequency modulation (FM)', 'Every cycle has the same height, but the instantaneous frequency is shifted by the message: cycles crowd together where the signal is high and stretch out where it dips. Counting cycles per unit time recovers the same message, and amplitude noise does not disturb it.']
  };

  function setFromEvent(e) {
    var rect = canvas.getBoundingClientRect();
    var x = e.clientX - rect.left;
    var t = chart.scales.x.getValueForPixel(x);
    t = Math.max(0, Math.min(1, t));
    t = Math.round(t / 0.005) * 0.005;
    var inp = document.getElementById('timeMarkerInput');
    inp.value = t;
    document.getElementById('timeMarkerVal').value = t.toFixed(3);
    window.update_timeMarker(t);
  }

  canvas.style.cursor = 'crosshair';
  canvas.addEventListener('pointerdown', function (e) {
    dragging = true; moved = false; downX = e.clientX; downY = e.clientY;
    setFromEvent(e);
    try { canvas.setPointerCapture(e.pointerId); } catch (err) { }
  });
  canvas.addEventListener('pointermove', function (e) {
    if (dragging) {
      if (Math.abs(e.clientX - downX) + Math.abs(e.clientY - downY) > 4) moved = true;
      setFromEvent(e);
      hideTooltip();
      return;
    }
    var rect = canvas.getBoundingClientRect();
    var band = bandAt(e.clientY - rect.top);
    if (band) { showTooltip(TIPS[band], e); canvas.style.cursor = 'pointer'; }
    else { hideTooltip(); canvas.style.cursor = 'crosshair'; }
  });
  canvas.addEventListener('pointerleave', function () { hideTooltip(); });
  canvas.addEventListener('pointerup', function (e) {
    dragging = false;
    if (!moved) {
      var rect = canvas.getBoundingClientRect();
      var band = bandAt(e.clientY - rect.top);
      if (band) showPopup(POPS[band][0], POPS[band][1]);
    }
  });

  /* ---------- demo step player ---------- */
  var STEPS = [
    { title: 'The message signal', narration: 'The black curve at the top is the slow information waveform — two crests and a trough. Everything below it is a fast radio carrier carrying this shape.', state: { carrierMode: 'both', showEnvelope: false, timeMarker: 0.15 } },
    { title: 'Scan the marker', narration: 'Drag the time marker across the figure. Where the black signal is high, the red AM wave is tall and the blue FM cycles crowd together; where the signal dips, AM shrinks and FM spreads out.', state: { carrierMode: 'both', showEnvelope: false, timeMarker: 0.5 } },
    { title: 'AM: message in the envelope', narration: 'Switch to AM. The peak spacing never changes, but the dashed envelope tracing the peak heights reproduces the original signal exactly.', state: { carrierMode: 'am', showEnvelope: true, timeMarker: 0.25 } },
    { title: 'FM: message in the spacing', narration: 'Switch to FM. Every cycle is the same height, yet counting cycles per unit time recovers the very same black curve.', state: { carrierMode: 'fm', showEnvelope: true, timeMarker: 0.5 } },
    { title: 'Same message, two encodings', narration: 'Compare both decoded curves: identical information, carried by two independent properties of the wave — which is why FM survives amplitude noise that would corrupt AM.', state: { carrierMode: 'both', showEnvelope: true, timeMarker: 0.8 } }
  ];
  var step = 0;

  function applyStep(i, silentMarker) {
    step = (i + STEPS.length) % STEPS.length;
    var s = STEPS[step];
    document.getElementById('demoTitle').textContent = s.title;
    document.getElementById('demoNarration').textContent = s.narration;
    document.getElementById('stepLabel').textContent = 'Step ' + (step + 1) + ' / ' + STEPS.length;

    var sel = document.getElementById('carrierModeInput');
    sel.value = s.state.carrierMode;
    window.toggle_carrierMode(s.state.carrierMode);

    var chk = document.getElementById('showEnvelopeInput');
    chk.checked = !!s.state.showEnvelope;
    window.toggle_showEnvelope(chk.checked);

    var sl = document.getElementById('timeMarkerInput');
    sl.value = s.state.timeMarker;
    document.getElementById('timeMarkerVal').value = (+s.state.timeMarker).toFixed(3);
    if (silentMarker) { markerT = +s.state.timeMarker; chart.render(); }
    else window.update_timeMarker(+s.state.timeMarker);
  }
  window.nextStep = function () { applyStep(step + 1); };
  window.prevStep = function () { applyStep(step - 1); };

  applyStep(0, true);   // default view: faithful to the source image (marker hidden)
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: The same slowly varying message signal can be encoded onto a fast radio carrier either by varying the carrier's amplitude (AM) or by varying its frequency (FM).
KEY INSIGHT (what students should walk away understanding): A wave has several independent properties, and any one of them can carry a message: AM writes the signal into the carrier's height, FM writes the same signal into the carrier's cycle spacing.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "The same slowly varying message signal can be encoded onto a fast radio carrier either by varying the carrier's amplitude (AM) or by varying its frequency (FM).",
  "figureType": "line_plot",
  "elements": [
    "Shared horizontal time axis (implicit, no tick labels) spanning the full width for all three stacked traces",
    "Top trace: smooth black low-frequency sine-like curve with two broad crests and one central trough, labeled 'Signal' at its right end",
    "Middle trace: red high-frequency carrier with uniform peak spacing and swelling/collapsing amplitude, labeled 'AM' at its right end",
    "Dashed red envelope curves (upper and lower) tracing the AM peak heights, mirroring the black signal shape",
    "Bottom trace: blue carrier with constant amplitude and varying cycle spacing — tight below signal crests, stretched below the signal trough — labeled 'FM' at its right end",
    "Vertical time marker line crossing all three traces, with small dots at each intersection",
    "Readout box reporting signal height, AM envelope height, and FM local cycle spacing / instantaneous frequency at the marker",
    "Reconstructed (decoded) black curve drawn above the active carrier when decoding is enabled",
    "Highlight/dim styling for the active vs. inactive carrier trace",
    "Small annotation callouts: 'amplitude varies, spacing constant' on AM; 'spacing varies, amplitude constant' on FM"
  ],
  "interactions": [
    {
      "id": "timeMarker",
