  var FM_Y  = 1.25, FM_A  = 1.15;   // blue FM carrier
  var REC_AM_Y = 3.70, REC_AM_A = 0.38;   // decoded-from-AM curve (in the AM/FM gap)
  var REC_FM_Y = 2.80, REC_FM_A = 0.33;   // decoded-from-FM curve

