  /* ---------- signal model ---------- */
  var P = 0.66, T0 = 0.14;      // slow message: crest ~0.14, trough ~0.47, crest ~0.80
  var FC_AM = 20;               // AM carrier cycles across the width
  var FC_FM = 18, DEV = 7;      // FM carrier + deviation (strong, visible crowding)

