    dAM.push({ x: t, y: amAt(t) });
    dEnvU.push({ x: t, y: AM_Y + AM_A * e });
    dEnvL.push({ x: t, y: AM_Y - AM_A * e });
    dFM.push({ x: t, y: fmAt(t) });
    dRecAM.push({ x: t, y: REC_AM_Y + REC_AM_A * m });
    dRecFM.push({ x: t, y: REC_FM_Y + REC_FM_A * m });
  }

  /* ---------- state ---------- */
  var markerT = 0.15, markerActive = false;
  var mode = 'both', showEnv = false;

  /* ---------- canvas ---------- */
  var container = document.getElementById('container');
  var canvas = document.createElement('canvas');
  canvas.style.cssText = 'width:100%;height:100%;display:block';
  container.appendChild(canvas);

  function baseOf(chart) {
    var b = Math.min((chart.width || 860) / 860, (chart.height || 690) / 690);
    return Math.max(0.45, Math.min(1.6, b));
  }
  function lw(mult, minPx) {
    return function (c) { return Math.max(minPx || 1.1, baseOf(c.chart) * mult); };
  }
  function dash(a, b2) {
    return function (c) { var k = baseOf(c.chart); return [Math.max(2, a * k), Math.max(2, b2 * k)]; };
  }
  function ds(id, data, color, width, minPx, dashFn) {
    return {
      _id: id, data: data, borderColor: color, backgroundColor: 'transparent',
      borderWidth: lw(width, minPx), borderDash: dashFn || undefined,
      pointRadius: 0, pointHitRadius: 0, tension: 0, fill: false,
      borderJoinStyle: 'round', borderCapStyle: 'round'
    };
  }

  var datasets = [
    ds('sig', dSig, C.sig, 3.6, 1.6),
    ds('envU', dEnvU, C.am, 1.9, 1.0, dash(6, 5)),
    ds('envL', dEnvL, C.am, 1.9, 1.0, dash(6, 5)),
    ds('am', dAM, C.am, 3.6, 1.6),
    ds('fm', dFM, C.fm, 3.6, 1.6),
    ds('recAM', dRecAM, C.rec, 1.9, 1.0, dash(7, 5)),
    ds('recFM', dRecFM, C.rec, 1.9, 1.0, dash(7, 5))
  ];
  datasets[1].hidden = datasets[2].hidden = datasets[5].hidden = datasets[6].hidden = true;

  /* ---------- overlay plugin ---------- */
  var overlay = {
    id: 'figOverlay',
    beforeLayout: function (chart) {
      var b = baseOf(chart);
      chart.options.layout.padding = {
        left: 3, top: Math.max(4, 5 * b), bottom: Math.max(3, 4 * b),
        right: Math.max(58, 74 * b)
      };
    },
    afterDatasetsDraw: function (chart) {
      var ctx = chart.ctx, ca = chart.chartArea, xs = chart.scales.x, ys = chart.scales.y;
      var b = baseOf(chart);
      ctx.save();

      /* --- right-margin trace labels (bold presence, as in the source) --- */
      var fs = Math.max(11, 17 * b);
      var sub = Math.max(8.5, 10.5 * b);
      ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
      var lx = ca.right + 7 * b;

      ctx.font = fs + 'px sans-serif';
      ctx.fillStyle = '#111';
      ctx.fillText('Signal', lx, ys.getPixelForValue(SIG_Y + SIG_A * mAt(1)));

      var amDim = (mode === 'fm'), fmDim = (mode === 'am');
      ctx.fillStyle = amDim ? '#a8a8a8' : '#111';
      ctx.fillText('AM', lx, ys.getPixelForValue(AM_Y) - (showEnv ? sub * 0.75 : 0));
      ctx.fillStyle = fmDim ? '#a8a8a8' : '#111';
      ctx.fillText('FM', lx, ys.getPixelForValue(FM_Y) - (showEnv ? sub * 0.75 : 0));

      if (showEnv) {
        ctx.font = sub + 'px sans-serif';
        ctx.fillStyle = amDim ? '#c3c3c3' : C.am;
        ctx.fillText('height varies', lx, ys.getPixelForValue(AM_Y) + sub * 0.95);
        ctx.fillStyle = fmDim ? '#c3c3c3' : C.fm;
        ctx.fillText('spacing varies', lx, ys.getPixelForValue(FM_Y) + sub * 0.95);
      }

      /* --- marker line + intersection dots --- */
      if (markerActive) {
        var px = xs.getPixelForValue(markerT);
        ctx.beginPath();
        ctx.setLineDash([Math.max(3, 4 * b), Math.max(3, 3 * b)]);
        ctx.lineWidth = Math.max(1, 1.4 * b);
        ctx.strokeStyle = C.marker;
        ctx.moveTo(px, ys.getPixelForValue(9.96));
        ctx.lineTo(px, ys.getPixelForValue(0.05));
        ctx.stroke();
        ctx.setLineDash([]);

        var r = Math.max(2.2, 4.0 * b);
        var dots = [
          [SIG_Y + SIG_A * mAt(markerT), C.sig],
          [amAt(markerT), amDim ? '#c0c0c0' : C.am],
          [fmAt(markerT), fmDim ? '#c0c0c0' : C.fm]
        ];
        if (showEnv && !amDim) {
          dots.push([AM_Y + AM_A * envAt(markerT), C.am]);
          dots.push([AM_Y - AM_A * envAt(markerT), C.am]);
          dots.push([REC_AM_Y + REC_AM_A * mAt(markerT), C.rec]);
        }
        if (showEnv && !fmDim) dots.push([REC_FM_Y + REC_FM_A * mAt(markerT), C.rec]);
        for (var k = 0; k < dots.length; k++) {
          ctx.beginPath();
          ctx.arc(px, ys.getPixelForValue(dots[k][0]), r, 0, 2 * Math.PI);
          ctx.fillStyle = dots[k][1]; ctx.fill();
          ctx.lineWidth = Math.max(0.7, 1.1 * b); ctx.strokeStyle = '#fff'; ctx.stroke();
        }

        /* --- floating readout, hugging the marker in the AM/FM gap --- */
        var t = markerT, mv = mAt(t), e = envAt(t), f = fInst(t);
        var lines = [['t = ' + t.toFixed(2) + '   m = ' + (mv >= 0 ? '+' : '') + mv.toFixed(2), '#333']];
        if (!amDim) lines.push(['AM height = ' + e.toFixed(2) + ' × max', C.am]);
        if (!fmDim) lines.push(['FM freq = ' + (f / FC_FM).toFixed(2) + ' × f' + '\u0063' + ',  gap ' + (100 / f).toFixed(1) + '% W', C.fm]);

        var rf = Math.max(9, 12 * b);
        ctx.font = rf + 'px sans-serif';
        var wmax = 0;
        for (var j = 0; j < lines.length; j++) wmax = Math.max(wmax, ctx.measureText(lines[j][0]).width);
        var pad = Math.max(5, 6 * b), lh = rf * 1.3;
        var bw = wmax + 2 * pad, bh = lines.length * lh + 1.4 * pad;
        var gapCy = ys.getPixelForValue(3.25);
        var by = Math.max(ca.top + 2, Math.min(ca.bottom - bh - 2, gapCy - bh / 2));
        var bx = px + 11 * b;
        if (bx + bw > ca.right - 2) bx = px - 11 * b - bw;
        if (bx < ca.left + 2) bx = ca.left + 2;

        ctx.fillStyle = 'rgba(255,255,255,0.94)';
        ctx.strokeStyle = 'rgba(0,0,0,0.25)';
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.rect(bx, by, bw, bh); ctx.fill(); ctx.stroke();
        ctx.textAlign = 'left'; ctx.textBaseline = 'top';
        for (var q = 0; q < lines.length; q++) {
          ctx.fillStyle = lines[q][1];
          ctx.fillText(lines[q][0], bx + pad, by + pad * 0.7 + q * lh + lh * 0.12);
        }
      }
      ctx.restore();
    }
  };

  /* ---------- chart ---------- */
  var chart = new Chart(canvas.getContext('2d'), {
    type: 'line',
    data: { datasets: datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: false,
      parsing: false,
      normalized: true,
      events: [],
      layout: { padding: { left: 3, right: 64, top: 5, bottom: 4 } },
      scales: {
        x: { type: 'linear', min: 0, max: 1, display: false },
        y: { type: 'linear', min: Y_MIN, max: Y_MAX, display: false }
      },
      plugins: { legend: { display: false }, tooltip: { enabled: false } }
    },
    plugins: [overlay]
  });
  window.__markRendered();

  document.addEventListener('fig-resize', function () { chart.resize(); });

  /* ---------- state application ---------- */
  function byId(id) { for (var i = 0; i < datasets.length; i++) if (datasets[i]._id === id) return datasets[i]; }
  function refresh() {
    byId('sig').borderColor = C.sig;
    byId('am').borderColor = (mode === 'fm') ? C.dim : C.am;
    byId('fm').borderColor = (mode === 'am') ? C.dim : C.fm;
    byId('envU').borderColor = byId('envL').borderColor = C.am;
    var envOn = showEnv && mode !== 'fm';
    byId('envU').hidden = !envOn;
    byId('envL').hidden = !envOn;
    byId('recAM').hidden = !envOn;
    byId('recFM').hidden = !(showEnv && mode !== 'am');
    chart.update('none');
  }

  window.update_timeMarker = function (v) {
    markerT = Math.max(0, Math.min(1, +v));
    markerActive = true;
    chart.render();
  };
  window.toggle_carrierMode = function (v) { mode = v; refresh(); };
  window.toggle_showEnvelope = function (on) { showEnv = !!on; refresh(); };

  /* ---------- pointer interaction ---------- */
  var dragging = false, moved = false, downX = 0, downY = 0;

  function bandAt(yPix) {
    var yv = chart.scales.y.getValueForPixel(yPix);
    if (yv > 7.75) return 'sig';
    if (yv > 3.30) return 'am';
    return 'fm';
  }
  var TIPS = {
    sig: 'Message signal — the slow information waveform to be transmitted.',
    am: 'AM carrier — cycle spacing is constant; the amplitude follows the signal.',
    fm: 'FM carrier — amplitude is constant; the cycle spacing follows the signal.'
  };
  var POPS = {
    sig: ['Message signal', 'This slow black curve is the information (for example audio) that must be sent. On its own it cannot travel far as a radio wave, so it is written onto a much faster carrier wave.'],
    am: ['Amplitude modulation (AM)', 'The carrier keeps a fixed frequency, so its peaks stay evenly spaced. Instead the height of each cycle is scaled by the message, so the outline (envelope) of the peaks reproduces the original signal. Because the information lives in the amplitude, amplitude noise corrupts it directly.'],
    fm: ['Frequency modulation (FM)', 'Every cycle has the same height, but the instantaneous frequency is shifted by the message: cycles crowd together where the signal is high and stretch out where it dips. Counting cycles per unit time recovers the same message, and amplitude noise does not disturb it.']
  };

  function setFromEvent(e) {
    var rect = canvas.getBoundingClientRect();
    var t = chart.scales.x.getValueForPixel(e.clientX - rect.left);
    t = Math.max(0, Math.min(1, t));
    t = Math.round(t / 0.005) * 0.005;
    document.getElementById('timeMarkerInput').value = t;
    document.getElementById('timeMarkerVal').value = t.toFixed(3);
    window.update_timeMarker(t);
  }

  canvas.style.cursor = 'crosshair';
  canvas.addEventListener('pointerdown', function (e) {
    dragging = true; moved = false; downX = e.clientX; downY = e.clientY;
    setFromEvent(e);
    try { canvas.setPointerCapture(e.pointerId); } catch (err) { }
  });
  canvas.addEventListener('pointermove', function (e) {
    if (dragging) {
      if (Math.abs(e.clientX - downX) + Math.abs(e.clientY - downY) > 4) moved = true;
      setFromEvent(e);
      hideTooltip();
      return;
    }
    var rect = canvas.getBoundingClientRect();
    var band = bandAt(e.clientY - rect.top);
    if (band) { showTooltip(TIPS[band], e); canvas.style.cursor = 'pointer'; }
    else { hideTooltip(); canvas.style.cursor = 'crosshair'; }
  });
  canvas.addEventListener('pointerleave', function () { hideTooltip(); });
  canvas.addEventListener('pointerup', function (e) {
    dragging = false;
    if (!moved) {
      var rect = canvas.getBoundingClientRect();
      var band = bandAt(e.clientY - rect.top);
      if (band) showPopup(POPS[band][0], POPS[band][1]);
    }
  });

  /* ---------- demo step player ---------- */
  var STEPS = [
    { title: 'The message signal', narration: 'The black curve at the top is the slow information waveform — two crests and a trough. Everything below it is a fast radio carrier carrying this same shape.', state: { carrierMode: 'both', showEnvelope: false, timeMarker: 0.15 } },
    { title: 'Scan the marker', narration: 'Drag the time marker across the figure. Where the black signal is high, the red AM wave is tall and the blue FM cycles crowd together; where the signal dips, AM shrinks to a waist and FM stretches out.', state: { carrierMode: 'both', showEnvelope: false, timeMarker: 0.47 } },
    { title: 'AM: message in the envelope', narration: 'Switch to AM. The peak spacing never changes, but the dashed envelope tracing the peak heights reproduces the original signal exactly — the decoded curve below it.', state: { carrierMode: 'am', showEnvelope: true, timeMarker: 0.25 } },
    { title: 'FM: message in the spacing', narration: 'Switch to FM. Every cycle is the same height, yet the cycles-per-second track follows the message: counting cycles recovers the very same black curve.', state: { carrierMode: 'fm', showEnvelope: true, timeMarker: 0.47 } },
    { title: 'Same message, two encodings', narration: 'Compare both decoded curves: identical information carried by two independent properties of the wave — which is why FM survives amplitude noise that would corrupt AM.', state: { carrierMode: 'both', showEnvelope: true, timeMarker: 0.80 } }
  ];
  var step = 0;

  function applyStep(i, silentMarker) {
    step = (i + STEPS.length) % STEPS.length;
    var s = STEPS[step];
    document.getElementById('demoTitle').textContent = s.title;
    document.getElementById('demoNarration').textContent = s.narration;
    document.getElementById('stepLabel').textContent = 'Step ' + (step + 1) + ' / ' + STEPS.length;

    var sel = document.getElementById('carrierModeInput');
    sel.value = s.state.carrierMode;
    window.toggle_carrierMode(s.state.carrierMode);

    var chk = document.getElementById('showEnvelopeInput');
    chk.checked = !!s.state.showEnvelope;
    window.toggle_showEnvelope(chk.checked);

    var sl = document.getElementById('timeMarkerInput');
    sl.value = s.state.timeMarker;
    document.getElementById('timeMarkerVal').value = (+s.state.timeMarker).toFixed(3);
    if (silentMarker) { markerT = +s.state.timeMarker; chart.render(); }
    else window.update_timeMarker(+s.state.timeMarker);
  }
  window.nextStep = function () { applyStep(step + 1); };
  window.prevStep = function () { applyStep(step - 1); };

  applyStep(0, true);   // default view is a faithful copy of the source (marker hidden)
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
