// @FIGURE_CODE_BEGIN
(function () {
  /* ---------- vertical layout in data units (0 = bottom, 10 = top) ----------
     Positions/amplitudes measured off the source image (860 x 690):
       signal centre  ~y 62px  amp ~57px   AM centre ~292px amp ~103px
       FM     centre  ~601px   amp ~71px                                    */
  var Y_MIN = 0, Y_MAX = 10;
  var SIG_Y = 9.08, SIG_A = 0.82;   // top black message curve
  var AM_Y  = 5.77, AM_A  = 1.50;   // red AM carrier
  var FM_Y  = 1.30, FM_A  = 1.05;   // blue FM carrier
  var REC_AM_Y = 3.72, REC_AM_A = 0.30;   // decoded-from-AM curve (in the AM/FM gap)
  var REC_FM_Y = 2.88, REC_FM_A = 0.27;   // decoded-from-FM curve

  var C = {
    sig: '#1a1a1a',
    am: '#c4402a',
    fm: '#4b6db5',
    dim: '#e0e0e0',
    rec: '#9a9a9a',
    marker: '#8d8d8d'
  };

  /* ---------- signal model ---------- */
  var P = 0.66, T0 = 0.14;      // slow message: crest ~0.14, trough ~0.47, crest ~0.80
  var FC_AM = 20;               // AM carrier cycles across the width
  var FC_FM = 23, DEV = 4.0;    // FM carrier + moderate deviation (as in the source)

  function mAt(t) { return Math.cos(2 * Math.PI * (t - T0) / P); }
  var S0 = Math.sin(2 * Math.PI * (-T0) / P);
  function intM(t) { return (P / (2 * Math.PI)) * (Math.sin(2 * Math.PI * (t - T0) / P) - S0); }
  function envAt(t) { return 0.6 + 0.4 * mAt(t); }            // 0.2 … 1.0
  function amAt(t) { return AM_Y + AM_A * envAt(t) * Math.sin(2 * Math.PI * FC_AM * t); }
  function fmAt(t) { return FM_Y + FM_A * Math.sin(2 * Math.PI * (FC_FM * t + DEV * intM(t))); }
  function fInst(t) { return FC_FM + DEV * mAt(t); }

  /* ---------- sampled data ---------- */
  var N = 2600;
  var dSig = [], dAM = [], dEnvU = [], dEnvL = [], dFM = [], dRecAM = [], dRecFM = [];
  for (var i = 0; i < N; i++) {
    var t = i / (N - 1);
    var m = mAt(t), e = envAt(t);
    dSig.push({ x: t, y: SIG_Y + SIG_A * m });
    dAM.push({ x: t, y: amAt(t) });
    dEnvU.push({ x: t, y: AM_Y + AM_A * e });
    dEnvL.push({ x: t, y: AM_Y - AM_A * e });
    dFM.push({ x: t, y: fmAt(t) });
    dRecAM.push({ x: t, y: REC_AM_Y + REC_AM_A * m });
    dRecFM.push({ x: t, y: REC_FM_Y + REC_FM_A * m });
  }

  /* ---------- state ---------- */
  var markerT = 0.15, markerActive = false;
  var mode = 'both', showEnv = false;

  /* ---------- canvas ---------- */
  var container = document.getElementById('container');
  var canvas = document.createElement('canvas');
  canvas.style.cssText = 'width:100%;height:100%;display:block';
  container.appendChild(canvas);

  function baseOf(chart) {
    var b = Math.min((chart.width || 860) / 860, (chart.height || 690) / 690);
    return Math.max(0.45, Math.min(1.7, b));
  }
  function lw(mult, minPx) {
    return function (c) { return Math.max(minPx || 1.1, baseOf(c.chart) * mult); };
  }
  function dash(a, b2) {
